<script>(function(){var type=document.getElementById('daType');function show(elements,visible){elements.forEach(function(el){el.classList.toggle('is-agenda-hidden',!visible);});}function sync(){var value=parseInt(type.value,10);show(document.querySelectorAll('.da-patient-fields'),value!==2);show(document.querySelectorAll('.da-procedure-fields'),value===1);show(document.querySelectorAll('.da-meeting-fields'),value===2);var procedure=document.querySelector('[name="id_procedimiento"]');if(procedure)procedure.required=value===1;}type.addEventListener('change',sync);if(window.jQuery)window.jQuery(type).off('change.agendaActivityFields').on('change.agendaActivityFields',sync);sync();})();</script>
<script>(function(){var form=document.querySelector('.js-activity-form'),type=document.getElementById('daType'),start=form?form.querySelector('[name="inicio" @if($admitted) readonly @endif]'):null,end=form?form.querySelector('[name="fin" @if($admitted) readonly @endif]'):null,box=form?form.querySelector('.da-availability__slots'):null,refresh=form?form.querySelector('.js-refresh-availability'):null;function esc(value){var div=document.createElement('div');div.textContent=String(value||'');return div.innerHTML;}function load(){if(!form||!start||!start.value||!box)return;var date=start.value.substring(0,10),url=form.getAttribute('data-availability-url')+'?fecha='+encodeURIComponent(date)+'&tipo='+encodeURIComponent(type.value),exclude=form.getAttribute('data-appointment-id');if(exclude)url+='&excluir='+encodeURIComponent(exclude);box.innerHTML='<span class="da-availability__hint"><i class="fas fa-spinner fa-spin mr-1"></i> Consultando horarios libres…</span>';fetch(url,{credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}}).then(function(response){return response.json().then(function(data){if(!response.ok)throw new Error(data.message||'No se pudo consultar la disponibilidad.');return data;});}).then(function(data){var items=data.items||[];box.innerHTML=items.length?items.map(function(item){return '<button type="button" class="da-availability__slot" data-start="'+esc(item.start)+'" data-end="'+esc(item.end)+'"><i class="far fa-clock mr-1"></i>'+esc(item.label)+'<small>Turno de '+item.minutes+' minutos</small></button>';}).join(''):'<span class="da-availability__hint da-availability__hint--empty">No existen intervalos libres para esta fecha y tipo de agenda.</span>';}).catch(function(error){box.innerHTML='<span class="da-availability__hint da-availability__hint--empty">'+esc(error.message)+'</span>';});}if(type)type.addEventListener('change',load);if(start)start.addEventListener('change',load);if(refresh)refresh.addEventListener('click',load);if(box)box.addEventListener('click',function(event){var slot=event.target.closest('.da-availability__slot');if(!slot)return;start.value=slot.getAttribute('data-start');end.value=slot.getAttribute('data-end');box.querySelectorAll('.da-availability__slot').forEach(function(item){item.classList.toggle('is-selected',item===slot);});});load();})();</script>
<script>(function(){var form=document.querySelector('.js-activity-form'),link=document.querySelector('[data-patient-create]');if(!form||!link)return;link.addEventListener('click',function(){var url=new URL(link.href,window.location.href),start=form.querySelector('[name="inicio"]'),end=form.querySelector('[name="fin"]'),type=form.querySelector('[name="tipo"]');if(start)url.searchParams.set('agenda_inicio',start.value);if(end)url.searchParams.set('agenda_fin',end.value);if(type)url.searchParams.set('agenda_tipo',type.value);link.href=url.toString();});})();</script>
<script>(function(){var searchForm=document.querySelector('.js-patient-search'),results=document.querySelector('.js-patient-results'),agendaForm=document.querySelector('.js-activity-form');if(!searchForm||!results||!agendaForm)return;var input=searchForm.querySelector('[name="paciente"]'),button=searchForm.querySelector('button[type="submit"]'),locked=results.getAttribute('data-patient-locked')==='1';function message(text){results.innerHTML='';var help=document.createElement('div');help.className='da-help';help.textContent=text;results.appendChild(help);}function render(items){var selected=agendaForm.querySelector('[name="id_paciente"]:checked'),selectedId=selected?String(selected.value):'';results.innerHTML='';if(!items.length){message('No se encontraron pacientes con ese criterio.');return;}var list=document.createElement('div');list.className='da-patient-list';items.forEach(function(item){var label=document.createElement('label');label.className='da-patient';var radio=document.createElement('input');radio.type='radio';radio.name='id_paciente';radio.value=item.id;radio.disabled=locked;radio.checked=String(item.id)===selectedId;radio.setAttribute('data-appointment-type',item.appointment_type||0);var text=document.createElement('span');text.textContent=item.name||item.text||item.id;var detail=document.createElement('small');detail.textContent=String(item.id)+(item.birth?' · '+item.birth:' · Sin fecha de nacimiento');text.appendChild(detail);label.appendChild(radio);label.appendChild(text);list.appendChild(label);});results.appendChild(list);}searchForm.addEventListener('submit',function(event){event.preventDefault();var query=(input.value||'').trim();if(query.length<2){message('Escribe al menos 2 caracteres para buscar.');input.focus();return;}button.disabled=true;message('Buscando pacientes…');fetch(searchForm.getAttribute('data-search-url')+'?q='+encodeURIComponent(query),{credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}}).then(function(response){return response.json().then(function(data){if(!response.ok)throw new Error(data.message||'No se pudo buscar al paciente.');return data;});}).then(function(data){render(data.items||data.results||[]);}).catch(function(error){message(error.message);}).then(function(){button.disabled=false;});});results.addEventListener('change',function(event){if(event.target.name!=='id_paciente')return;var appointmentType=event.target.getAttribute('data-appointment-type')||'0',appointmentTypeSelect=agendaForm.querySelector('.js-appointment-type-display'),appointmentTypeValue=agendaForm.querySelector('.js-appointment-type-value');if(appointmentTypeSelect)appointmentTypeSelect.value=appointmentType;if(appointmentTypeValue)appointmentTypeValue.value=appointmentType;});})();</script>
